#include <bits/stdc++.h>
#define FOR(i,a,b) for(int i=(a),end##i(b);i<=end##i;i++)
#define REV(i,a,b) for(int i=(a),end##i(b);i>=end##i;i--)
using namespace std;
const int MAXN=505;
int n,m,mod;
int update(const int &x){
	if(x<0)return x+mod;
	if(x>=mod)return x-mod;
	return x;
}
void add(int &x,const int &y){
	x=update(x+y);
}
int power(int x,int k){
	int ans=1;
	while(k){
		if(k&1)ans=1ll*ans*x%mod;
		x=1ll*x*x%mod;
		k>>=1;
	}
	return ans;
}
int factorial[MAXN*4],inv_factorial[MAXN*4];
void initialize(int n){
	factorial[0]=1;
	FOR(i,1,n)factorial[i]=1ll*factorial[i-1]*i%mod;
	inv_factorial[n]=power(factorial[n],mod-2);
	REV(i,n-1,0)inv_factorial[i]=1ll*inv_factorial[i+1]*(i+1)%mod;	
}
int C(int n,int m){
	if(n<0||m<0||n<m)return 0;
	return 1ll*factorial[n]*inv_factorial[n-m]%mod*inv_factorial[m]%mod;
}
vector<int> f,g;
int sumN(int n){
	return n*(n+1)/2;
}
vector<int> multiply(const vector<int> &A ,const vector<int> &B){
	vector<int> C(A.size()+B.size()-1);
	FOR(i,0,(int)A.size()-1)FOR(j,0,(int)B.size()-1)add(C[i+j],1ll*A[i]*B[j]%mod);
	return C;
}
int G(int n,int m){
	return C(m+n-1,n-1);	
}
int main(){
#ifdef pig
	freopen("1439D.in","r",stdin);
	freopen("1439D.out","w",stdout);
#endif
	cin>>m>>n>>mod;
	initialize(m<<1);
	f.resize(n+1);g.resize(n+1);
	f[0]=1;
	FOR(i,1,n){
		FOR(j,0,i-1)add(f[i],1ll*f[j]*f[i-1-j]%mod*C(i-1,j)%mod);
		f[i]=1ll*f[i]*(i+1)%mod;
	}
	FOR(i,1,n){
		FOR(j,0,i-1)add(g[i],(2ll*f[j]*g[i-1-j]%mod*C(i-1,j)%mod*(i+1)%mod+1ll*C(i-1,j)*(sumN(j)+sumN(i-1-j))%mod*f[j]%mod*f[i-1-j]%mod)%mod);
	}
	f[0]=0;
	FOR(i,0,n)g[i]=1ll*g[i]*inv_factorial[i]%mod;
	FOR(i,0,n)f[i]=1ll*f[i]*inv_factorial[i]%mod;
	int ans=0;
	FOR(i,1,m-n+1){
		add(ans,1ll*g[n]*G(i+1,m-n-i+1)%mod*factorial[n]%mod*i%mod);		
		g=multiply(g,f);g.resize(n+1);
	}
	cout<<ans;
	return 0;
}
